<script setup>import{Head,usePage}from'@inertiajs/vue3';import{computed}from'vue';const props=defineProps({title:String,description:{type:String,default:''},canonical:String,image:String,type:{type:String,default:'website'},robots:{type:String,default:'index,follow'},schema:Object,imageAlt:String});const page=usePage(),store=computed(()=>page.props.store||{}),base=computed(()=>String(store.value.url||'').replace(/\/$/,''));const abs=v=>!v?base.value:(/^https?:\/\//i.test(v)?v:`${base.value}/${String(v).replace(/^\//,'')}`);const url=computed(()=>abs(props.canonical||page.url)),img=computed(()=>abs(props.image||store.value.logo||'/assets/prinx-logo.svg')),json=computed(()=>props.schema?JSON.stringify(props.schema).replace(/</g,'\\u003c'):'');</script><template><Head :title="title"><meta head-key="description" name="description" :content="description"><meta head-key="robots" name="robots" :content="robots"><link head-key="canonical" rel="canonical" :href="url"><meta head-key="og:type" property="og:type" :content="type"><meta head-key="og:title" property="og:title" :content="title"><meta head-key="og:description" property="og:description" :content="description"><meta head-key="og:url" property="og:url" :content="url"><meta head-key="og:image" property="og:image" :content="img"><meta head-key="twitter:card" name="twitter:card" content="summary_large_image"><script v-if="schema" head-key="structured-data" type="application/ld+json" v-html="json"></script></Head></template>
